<script setup>
import { onMounted, onUnmounted, ref, watch } from 'vue'
import { Search, RotateCw, ArrowUpRight, ChevronLeft, ChevronRight, SlidersHorizontal } from 'lucide-vue-next'
import { post, money, date, statusLabel } from '../api'
const query = ref(''), statuses = ref([]), from = ref(''), to = ref(''), min = ref(''), max = ref(''), page = ref(1)
const result = ref({orders: [], total: 0, revenue: 0, by_status: {}}), busy = ref(false), error = ref('')
let timer, requestId = 0
async function load() {
  const id = ++requestId; busy.value = true; error.value = ''
  try { const response = await post('/search/orders', {query: query.value, statuses: statuses.value, date_from: from.value || null, date_to: to.value || null, min_price: min.value === '' ? null : Number(min.value), max_price: max.value === '' ? null : Number(max.value), page: page.value}); if (id === requestId) result.value = response }
  catch(e) { if (id === requestId) error.value = e.message } finally { if (id === requestId) busy.value = false }
}
watch([query, statuses, from, to, min, max], () => {clearTimeout(timer); requestId++; page.value = 1; timer = setTimeout(load, 250)}, {deep: true})
function reset() { query.value = ''; statuses.value = []; from.value = ''; to.value = ''; min.value = ''; max.value = '' }
function paginate(step) { page.value += step; load() }
onMounted(load); onUnmounted(() => {clearTimeout(timer); requestId++})
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">THE BIG PICTURE, IN THE DETAILS</p><h1>Order search<span class="blue-dot">.</span></h1></div><button class="secondary" @click="load" :disabled="busy"><RotateCw :size="16"/>Refresh</button></div>
  <div class="dashboard-layout"><aside class="filter-panel" v-reveal><h3><SlidersHorizontal :size="17"/>Refine orders</h3><label class="field-label">Order status</label><label v-for="s in ['PENDING', 'PROCESSING', 'SHIPPED']" :key="s" class="checkbox-row"><input type="checkbox" v-model="statuses" :value="s"/><span class="status-dot" :class="s.toLowerCase()"></span>{{statusLabel(s)}}</label><div class="filter-section"><label class="field-label">Date range</label><label class="input-label">From<input type="date" v-model="from"/></label><label class="input-label">To<input type="date" v-model="to"/></label></div><div class="filter-section"><label class="field-label">Order value</label><div class="price-inputs"><label class="input-label">Minimum<input type="number" min="0" v-model="min" placeholder="$0"/></label><label class="input-label">Maximum<input type="number" min="0" v-model="max" placeholder="Any"/></label></div><input type="range" min="0" max="1000" step="10" :value="max === '' ? 1000 : max" @input="max = Number($event.target.value)" aria-label="Maximum order value"/></div><button class="text-button" @click="reset">Reset all filters</button></aside>
    <section class="search-results"><label class="search-input large"><Search :size="20"/><input v-model="query" placeholder="Search customers, products, or a little of both…" aria-label="Search orders"/><span class="search-hint">Try “Wireless”</span></label>
      <div v-if="error" class="notice error" role="alert">{{error}}<button class="text-button" @click="load">Try again</button></div>
      <template v-else><div class="kpi-grid" v-reveal :class="{loadingdata: busy}"><article class="kpi revenue"><span>Filtered revenue <ArrowUpRight :size="17"/></span><strong>{{money(result.revenue)}}</strong><small>{{result.total}} matching orders</small></article><article v-for="s in ['PENDING','PROCESSING','SHIPPED']" :key="s" class="kpi"><span><i class="status-dot" :class="s.toLowerCase()"></i>{{statusLabel(s)}}</span><strong>{{result.by_status[s] || 0}}</strong><small>orders in this view</small></article></div>
      <div class="results-heading"><h3>All orders <span class="count">{{result.total}}</span></h3><span>{{busy ? 'Updating…' : 'Most recent first'}}</span></div><div class="table-wrap" v-reveal :class="{loadingdata: busy}" :aria-busy="busy"><table><thead><tr><th>Order</th><th>Date</th><th>Customer</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="order in result.orders" :key="order.order_id"><td><router-link class="order-link" :to="`/admin/orders/${order.order_id}`">#{{String(order.order_id).padStart(4,'0')}}</router-link></td><td>{{date(order.order_date)}}</td><td><div class="table-customer"><span class="small-avatar">{{order.customer.name.split(' ').map(n => n[0]).join('')}}</span><div><strong>{{order.customer.name}}</strong><small>{{order.customer.email}}</small></div></div></td><td class="amount">{{money(order.total_amount)}}</td><td><span class="status" :class="order.status.toLowerCase()">{{statusLabel(order.status)}}</span></td><td><router-link :to="`/admin/orders/${order.order_id}`" :aria-label="`View order ${order.order_id}`"><ArrowUpRight :size="17"/></router-link></td></tr></tbody></table><div v-if="!result.orders.length" class="empty compact"><Search :size="30"/><h3>No orders match just yet.</h3><p>Try broadening your search or clearing the filters.</p></div></div><div class="pagination" v-reveal><span>{{result.total ? (page-1)*10+1 : 0}}–{{Math.min(page*10,result.total)}} of {{result.total}} orders</span><div><button class="icon-button" :disabled="page === 1 || busy" @click="paginate(-1)" aria-label="Previous page"><ChevronLeft :size="18"/></button><span>Page {{page}}</span><button class="icon-button" :disabled="page*10 >= result.total || busy" @click="paginate(1)" aria-label="Next page"><ChevronRight :size="18"/></button></div></div></template>
    </section></div>
</template>
